def diameterOfBinaryTree(root):
    max_d = 0

    def depth(node):
        nonlocal max_d
        if not node:
            return 0
        left_depth = depth(node.left)
        right_depth = depth(node.right)
        max_d = max(max_d, left_depth + right_depth)
        return 1 + max(left_depth, right_depth)

    depth(root)
    return max_d

