def lowestCommonAncestor(root, p, q):
    # 判题约定：p、q 以节点值传入（判题器传不了树内节点引用），先按值定位
    def find(node, val):
        if not node:
            return None
        if node.val == val:
            return node
        return find(node.left, val) or find(node.right, val)

    p, q = find(root, p), find(root, q)

    def lca(node):
        if not node or node is p or node is q:
            return node
        left = lca(node.left)
        right = lca(node.right)
        if left and right:
            return node
        return left or right

    return lca(root)

